// 免修：
//   - approved（有效）：依据非空、目标要求必须存在于该学生名下；同一学生
//     同一要求只能有一份有效免修；
//   - revoked（已撤销）：撤销只取消它对要求的满足作用，曾经有效的申请所
//     必需的信息仍须保留——目标要求必须真实存在于该学生名下（要求编号为
//     空、要求根本不存在、同号要求只属于另一名学生都不通过），原依据必须
//     含非空白内容（缺失、空串或全为空格/制表符/换行都不通过）；
//   - rejected（已拒绝）：允许指向当时不存在的要求、允许依据为空——申请
//     被拒绝本身就可能是因为要求不存在或依据为空，这类正常历史不能按
//     已撤销记录的条件误判为文件损坏。
// 检查只读取内容、不改动记录：依据中实际文字两侧及内部原有的空白都原样
// 保留，不为检查而改写保存下来的材料。
approvedReq := map[string]string{} // student+"\x00"+req -> waiverID
for _, w := range d.Waivers {
	if w == nil {
		return errors.New("存在空的免修记录")
	}
	if w.StudentID == "" || w.ID == "" {
		return errors.New("存在缺少学生编号或免修编号的免修记录")
	}
	if _, ok := s.studentByID[w.StudentID]; !ok {
		return fmt.Errorf("免修 %s 引用了不存在的学生 %s", w.ID, w.StudentID)
	}
	switch w.Status {
	case WaiverApproved, WaiverRejected, WaiverRevoked:
	default:
		return fmt.Errorf("学生 %s 的免修 %s 含非法状态 %q", w.StudentID, w.ID, w.Status)
	}
	// effective 表示这份申请曾经/正在有效：批准态与撤销态都必须携带一份
	// 有效申请所必需的信息（本人名下真实存在的要求 + 含实际文字的依据）。
	var effective bool
	switch w.Status {
	case WaiverApproved:
		effective = true
	case WaiverRevoked:
		effective = true
	}
	if effective {
		rk := reqKey(w.StudentID, w.ReqID)
		if w.ReqID == "" || s.reqByKey[rk] == nil {
			return fmt.Errorf(
				"学生 %s 的已撤销免修 %s 目标要求无效：要求编号 %q 为空或不存在于该学生名下",
				w.StudentID, w.ID, w.ReqID)
		}
		if strings.TrimSpace(w.Basis) == "" {
			return fmt.Errorf(
				"学生 %s 的已撤销免修 %s 原依据为空：缺少依据、空字符串或全为空白",
				w.StudentID, w.ID)
		}
	}
	if w.Status == WaiverApproved {
		rk := reqKey(
			w.StudentID,
			w.ReqID,
		)
		if other, dup := approvedReq[rk]; dup {
			return fmt.Errorf("学生 %s 的要求 %s 同时存在有效免修 %s 与 %s",
				w.StudentID, w.ReqID, other, w.ID)
		}
		approvedReq[rk] = w.ID
	}

