		assertCLIRevokedCorruptAccess(t, file, raw,
			[]string{"show", "s1"}, "s1", "wv", "原依据为空", "show")
		assertCLIRevokedCorruptAccess(t, file, raw,
			[]string{"waiver", "s1", "r1", "w2", "新申请依据"},
			"s1", "wv", "原依据为空", "写入类命令 waiver")
